#define N2_ID 1
#define H_ID 2
#define O_ID 3
#define OH_ID 4
#define HO2_ID 5
#define H2_ID 6
#define H2O_ID 7
#define H2O2_ID 8
#define O2_ID 9
#define CH3_ID 10
#define CH4_ID 11
#define HCO_ID 12
#define CH2O_ID 13
#define CH3O_ID 14
#define CH3OH_ID 15
#define CO_ID 16
#define CO2_ID 17
